command:
const targets = Array.from(game.user.targets);
if (!targets.length) return ui.notifications.warn("Please target at least one token!");


const data = await foundry.applications.api.DialogV2.input({
  window: { title: "Edit HP/SP" },
  content: `
    <div class="form-group">
      <label>Edit HP/SP</label>
      <div class="form-fields">
        <input type="text" name="adjustment" placeholder="0" autofocus>
      </div>
    </div>`,
  ok: { label: "Apply", icon: "fa-solid fa-burst" }
});

if (!data || !data.adjustment) return;

const matches = data.adjustment.match(/[+-]?\d+/g);
if (!matches) return ui.notifications.error("No valid numbers found.");
const totalAdj = matches.reduce((acc, num) => acc + parseInt(num), 0);

for (let token of targets) {
  const actor = token.actor;

  const hpPath = "system.health.value";
  const hpMaxPath = "system.health.max";
  const spPath = "system.spirit.value";
  const spMaxPath = "system.spirit.max";

  const currentHP = foundry.utils.getProperty(actor, hpPath);
  const maxHP = foundry.utils.getProperty(actor, hpMaxPath);
  const currentSP = foundry.utils.getProperty(actor, spPath);
  const maxSP = foundry.utils.getProperty(actor, spMaxPath);

  if (currentHP === undefined || maxHP === undefined || currentSP === undefined || maxSP === undefined) {
    console.warn(`Plume | ${token.name} is missing Health or Spirit data.`);
    continue;
  }

  const newHP = Math.max(-999, Math.min(maxHP, currentHP + totalAdj));
  const newSP = Math.max(-999, Math.min(maxSP, currentSP + totalAdj));

  await actor.update({ 
    [hpPath]: newHP,
    [spPath]: newSP
  });

  await ChatMessage.create({
    speaker: ChatMessage.getSpeaker({ token: token.document }),
    content: `
      <div class="dice-roll">
        <div class="dice-result">
          <div class="dice-total" style="color: #000000; border: 1px solid #000;"> 
            ${totalAdj >= 0 ? "+" : ""}${totalAdj} HP/SP 
          </div>
          <div style="font-size: 0.9em; text-align: center; margin-top: 4px;">
            <strong>HP:</strong> ${currentHP} → ${newHP} | <strong>SP:</strong> ${currentSP} → ${newSP}
          </div>
        </div>
      </div>`,
    sound: CONFIG.sounds.dice
  });
}
